from collections import Counter

def count_triples(N, K):
    count = 0
    mod_counts = Counter()
    for a in range(1, N + 1):
        mod_counts[a % K] += 1
    for b in range(1, N + 1):
        if (b % K) == 0:
            count += mod_counts[0]
        else:
            count += mod_counts[K - (b % K)]
    return count * 3

if __name__ == "__main__":
    N, K = map(int, sys.stdin.readline().split())
    result = count_triples(N, K)
